+ * Apply `.arq-material` to a floating control surface. Do not apply it to
+ * model content, to a docked panel (which already has an edge against the
+ * canvas), or to a full-viewport element.
+ */
+@import '../tokens.css';
+@import '../shell/shell-tokens.css';
+
+:root {
+  /* Tuned so the surface reads as chrome without the content behind it
+     becoming legible through it - a control you can read the model through is
+     worse than either a solid panel or no panel. Blur and saturation follow
+     the design package's `glass-materials.json` regular variant. */
+  --arq-material-tint: rgb(252 252 253 / 72%);
+  --arq-material-filter: saturate(165%) blur(28px);
+  --arq-material-border: rgb(0 0 0 / 10%);
+
+  /* The `strong` variant, for the large presentations that have to stay
+     legible over busy content: the inspector, the open-project surface and
+     recovery. More tint rather than only more blur - blur alone raises cost
+     without raising legibility, and legibility is the whole reason this
+     variant exists. */
+  --arq-material-tint-strong: rgb(252 252 253 / 88%);
+  --arq-material-filter-strong: saturate(165%) blur(34px);
+
