+      data-lens-measured={
+        indicator === null ? 'no' : `${Math.round(indicator.width)}x${Math.round(indicator.height)}`
+      }
+      /*
+       * Not a material, deliberately.
+       *
+       * The capsule sits inside the top bar, which is one - and ADR-0031
