+      name: 'dark',
+      options: { colorScheme: 'dark' },
+      expect: { quality: 'refraction', lens: true, opaque: false },
+    },
+    {
+      name: 'forced-colors',
+      options: { forcedColors: 'active' },
+      expect: { quality: 'off', lens: false, opaque: true },
+    },
+    {
